from typing import List
import itertools
import math

def solve_octagon_prob(nums: List[int]) -> int:
    def is_right_triangle(a: int, b: int, c: int) -> bool:
        sides = [a, b, c]
        sides.sort()
        return math.isclose(sides[0]**2 + sides[1]**2, sides[2]**2)

    def is_arithmetic_progression(a: int, b: int, c: int) -> bool:
        return abs(b - a) == abs(c - b)

    count = 0
    for triangle in itertools.combinations(nums, 3):
        if is_right_triangle(*triangle) and is_arithmetic_progression(*triangle):
            count += 1

    total_triangles = math.comb(len(nums), 3)
    probability = count / total_triangles
    m, n = 0, 0
    def gcd(a: int, b: int) -> int:
        while b != 0:
            a, b = b, a % b
        return a

    g = nums[0]
    for num in nums:
        g = gcd(g, num)

    m = count // g
    n = total_triangles // g
    return m + n

