from typing import List
import itertools
import math

def is_arithmetic_progression(numbers: List[int]) -> bool:
    """Check if the given numbers form an arithmetic progression."""
    return len(set(numbers[i] - numbers[i-1] for i in range(2, len(numbers)))) == 1


def is_right_triangle(a: int, b: int, c: int) -> bool:
    """Check if the triangle with sides a, b, and c is a right triangle."""
    return math.sqrt(a**2 + b**2) == c or math.sqrt(b**2 + c**2) == a or math.sqrt(c**2 + a**2) == b


def solve_octagon_prob(numbers: List[int]) -> int:
    """Calculate the probability that the chosen triangle is a right triangle and 
    the three numbers assigned to its vertices form an arithmetic progression."""
    count = 0
    for combination in itertools.combinations(numbers, 3):
        if is_arithmetic_progression(combination) and is_right_triangle(*combination):
            count += 1
    total_combinations = len(list(itertools.combinations(numbers, 3)))
    return sum(count // c for c in range(1, total_combinations + 1))
