from typing import List
import itertools
import math

def is_right_triangle(a: int, b: int, c: int) -> bool:
    """Check if a triangle with sides a, b, and c is right."""
    return (a ** 2 + b ** 2 == c ** 2) or (b ** 2 + c ** 2 == a ** 2) or (c ** 2 + a ** 2 == b ** 2)

def is_arithmetic_progression(a: int, b: int, c: int) -> bool:
    """Check if three numbers form an arithmetic progression."""
    return abs(b - a) == abs(c - b)

def solve_octagon_prob(vertices: List[int]) -> int:
    """
    Calculate the probability that a chosen triangle is a right triangle
    and its vertices form an arithmetic progression.

    Args:
        vertices (List[int]): A list of eight natural numbers assigned to the octagon's vertices.

    Returns:
        int: The numerator plus denominator of the probability in simplest form.
    """
    total_triangles = math.comb(8, 3)
    right_arithmetic_triangles = sum(
        1
        for (a, b, c) in itertools.permutations(vertices)
        if is_right_triangle(a, b, c) and is_arithmetic_progression(a, b, c)
    )
    probability = right_arithmetic_triangles / total_triangles
    return int(probability.as_integer_ratio()[0]) + int(probability.as_integer_ratio()[1])
