def solve_min_products(fixed_cost: int, variable_cost: int, selling_price: int) -> int:
    """
    This function calculates the minimum number of products that must be produced and sold 
    for the business to start making a profit.

    Args:
        fixed_cost (int): The fixed monthly cost in VND.
        variable_cost (int): The variable cost per product in VND.
        selling_price (int): The price at which each product is sold in VND.

    Returns:
        int: The minimum number of products that must be produced and sold for the business to start making a profit.
    """

    # Calculate the total revenue without tax
    def calculate_revenue(x: int) -> float:
        return (x * selling_price) - (fixed_cost + variable_cost * x)

    # Define the tax rates based on the quantity sold
    def calculate_tax_rate(x: int) -> float:
        if x < 100:
            return 0.10
        elif 100 <= x < 300:
            return 0.08
        else:
            return 0.05

    # Calculate the total revenue with tax applied
    def calculate_total_revenue(x: int) -> float:
        return (calculate_revenue(x)) * (1 + calculate_tax_rate(x))

    # Initialize x to 1 and increment until a profit is made
    x = 1
    while True:
        if calculate_total_revenue(x) > fixed_cost:
            break
        x += 1

    return x

