def solve_min_products(fixed_cost: int, variable_cost: int, selling_price: int) -> int:
    """
    Calculate the minimum number of products that must be produced and sold for the business to start making a profit.

    Args:
        fixed_cost (int): The fixed monthly cost in VND.
        variable_cost (int): The variable cost per product in VND.
        selling_price (int): The price at which each product is sold in VND.

    Returns:
        int: The minimum number of products that must be produced and sold for the business to start making a profit.
    """
    def calculate_profit(x: int) -> float:
        """Calculate the profit based on the given quantity."""
        total_revenue = x * selling_price
        tax_rate = get_tax_rate(x)
        total_tax = (total_revenue * tax_rate) / 100
        return total_revenue - fixed_cost - variable_cost * x - total_tax

    def get_tax_rate(x: int) -> float:
        """Determine the tax rate based on the quantity sold."""
        if x < 100:
            return 10.0
        elif 100 <= x < 300:
            return 8.0
        else:
            return 5.0

    def binary_search(low: int, high: int) -> NoReturn:
        """Perform a binary search to find the minimum number of products."""
        while low <= high:
            mid = (low + high) // 2
            profit = calculate_profit(mid)
            if profit > 0:
                return mid
            elif profit < 0:
                low = mid + 1
            else:
                high = mid - 1

    return binary_search(0, 10**6)

