def count_ap_triplets(n: int, limit: int) -> int:
    """
    Counts the number of ways to choose three distinct cards from a box containing n cards,
    such that their numbers form an arithmetic progression and their sum does not exceed limit.

    Args:
        n (int): The total number of cards in the box.
        limit (int): The maximum sum allowed for the three card numbers.

    Returns:
        int: The number of ways to choose 3 cards satisfying the conditions.
    """

    def count_ap_triplets_helper(a: int, d: int) -> int:
        """
        Recursive helper function to count AP triplets with a common difference d and first term a.
        """
        if a + d * 3 > n or a + d * 2 > limit:
            return 0
        elif a + d * 3 <= limit:
            return 1 + count_ap_triplets_helper(a, d) + count_ap_triplets_helper(a + d, d)
        else:
            return count_ap_triplets_helper(a, d)

    count = 0
    for i in range(1, n):
        for j in range(i + 1, n):
            if (j - i) % 2 == 0:  # Ensure common difference is even
                count += count_ap_triplets_helper(i, (j - i) // 2)
    return count

