def count_ap_triplets(n: int, max_sum: int) -> int:
    def is_valid(a: int, d: int) -> bool:
        return a + (2 * d) <= max_sum and a > 0

    def count_progressions() -> int:
        count = 0
        for a in range(1, n):
            for d in range(1, n - a):
                if is_valid(a, d):
                    count += 1
        return count

    def count_triplets_with_fixed_d(d: int) -> List[Tuple[int]]:
        triplets = []
        for a in range(1, (max_sum - 2 * d) // 3 + 1):
            if is_valid(a, d):
                triplets.append((a, a + d, a + 2 * d))
        return triplets

    def count_triplets() -> int:
        count = 0
        for d in range(1, n - 1):
            triplets = count_triplets_with_fixed_d(d)
            count += len(triplets)
        return count

    return count_progressions()

