from typing import List
import itertools

def count_grid_ways(numbers: List[int]) -> int:
    """
    Count the number of ways to choose six distinct numbers from the set {2, 3, ..., 11}
    and place them into a grid such that the sum of numbers in each row is equal.

    Args:
        numbers (List[int]): A list of integers representing the available numbers.

    Returns:
        int: The number of ways to fill the grid.
    """
    def is_valid_grid(grid: List[List[int]]) -> bool:
        """
        Check if a given grid satisfies the conditions.

        Args:
            grid (List[List[int]]): A 3x1, 2x1 or 1x1 grid filled with numbers from the set {2, 3, ..., 11}.

        Returns:
            bool: True if the grid is valid, False otherwise.
        """
        # Check if each row has a sum equal to the total sum of all numbers
        for i in range(3):
            row_sum = sum(grid[i])
            if row_sum != (sum(numbers) // 3) * (i + 1):
                return False

        return True

    def generate_grids() -> List[List[List[int]]]:
        """
        Generate all possible grids.

        Returns:
            List[List[List[int]]]: A list of valid grids.
        """
        # Generate all permutations of the numbers
        perms = itertools.permutations(numbers, 6)

        # Initialize an empty list to store valid grids
        valid_grids = []

        for perm in perms:
            # Try to fill a grid with the current permutation
            for i in range(3):
                row = []
                for j in range(i + 1):
                    if len(row) < (i + 1):
                        row.append(perm[j])
                if len(row) == (i + 1):
                    # Check if the remaining numbers can be used to fill the rest of the grid
                    remaining_nums = perm[i+1:]
                    for j in range(i, 3):
                        row2 = []
                        for k in range(j - i + 1):
                            if len(row2) < (j - i + 1):
                                row2.append(remaining_nums[k])
                        if len(row2) == (j - i + 1):
                            # Check if the remaining numbers can be used to fill the rest of the grid
                            remaining_nums = [x for x in remaining_nums if x not in row2]
                            row3 = []
                            for k in range(j - i, 3 - j):
                                if len(row3) < (3 - j):
                                    row3.append(remaining_nums[k])
                            if len(row3) == (3 - j):
                                # Check if the current grid is valid
                                grid = [row, row2, row3]
                                if is_valid_grid(grid):
                                    valid_grids.append(grid)

        return valid_grids

    grids = generate_grids()
    return len(grids)

from typing import Callable, Tuple
import numpy as np

def maximize_profit(*coeffs: float) -> int:
    """
    Find the number of products x that the factory should produce each month to maximize the total profit.

    Args:
        coeffs (Tuple[float]): Coefficients of the cost and price functions.
            coeffs[0]: Constant term in C(x)
            coeffs[1]: Linear term coefficient in C(x)
            coeffs[2]: Quadratic term coefficient in C(x)
            coeffs[3]: Cubic term coefficient in C(x)
            coeffs[4]: Constant term in p(x)
            coeffs[5]: Linear term coefficient in p(x)

    Returns:
        int: The number of products x that the factory should produce each month to maximize the total profit.
    """

    # Unpack coefficients
    c0, c1, c2, c3, p0, p1 = coeffs

    # Define the cost and price functions
    def C(x: float) -> float:
        return 1000 * (c0 + c1*x - c2*x**2 + c3*x**3)

    def p(x: float) -> float:
        return 1000 * (p0 - p1*x)

    # Define the profit function
    def P(x: float) -> float:
        return p(x) * x - C(x)

    # Find the derivative of the profit function
    def dP_dx(x: float) -> float:
        return 1000 * (p1 * x + p(x) - c1 - 2*c2*x + 3*c3*x**2)

    # Use numerical methods to find the root of the derivative, which corresponds to the maximum profit
    from scipy.optimize import fsolve

    def func(x: float) -> float:
        return dP_dx(x)

    x_max = fsolve(func, 100)[0]

    # Round the result to the nearest integer
    return round(x_max)

