import math

def calculate_probability_score(num_questions: int, num_options: int, correct_points: int, incorrect_points: int, target_score: int) -> float:
    if target_score < 0 or target_score > num_questions * correct_points:
        return 0.0

    total_outcomes = num_options ** num_questions
    desired_outcomes = 0

    for i in range(num_questions + 1):
        for j in range(i, num_questions + 1):
            if (i * correct_points) + (j * incorrect_points) == target_score:
                combinations = math.comb(num_questions, i)
                combinations *= math.comb(num_questions - i, j - i)
                desired_outcomes += combinations

    probability = desired_outcomes / total_outcomes
    return round(probability * 100, 2)

