def calculate_p(n, k, scale):
    p = 0
    for i in range(k + 1):
        # Calculate the number of ways to choose i slots with exactly one book
        ways_to_choose_i_slots_with_one_book = math.comb(n - 2 * i, i)

        if i == 4 or i == 6:
            # Calculate the number of ways to distribute k books into n slots such that 
            # no slot contains more than two books and any slot containing two books must be surrounded by empty slots
            ways_to_distribute_k_books = math.comb(n, k) * (math.comb(i, 4) if i == 4 else math.comb(i, 6)) * \
                                          math.prod(math.comb(2 * j + 1, 2) for j in range(k - i))

            # Add the product of these two numbers to p
            p += ways_to_choose_i_slots_with_one_book * ways_to_distribute_k_books

    return scale * p / math.comb(n, k)

