import random
import math

def is_prime(n: int) -> bool:
    """Check if a number is prime."""
    if n < 2:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def calculate_probability(total_tickets: int, num_drawn: int) -> float:
    """Calculate the probability of drawing at least two prime numbers and an even sum."""
    # Generate all possible ticket combinations
    tickets = list(range(1, total_tickets + 1))
    combinations = []
    for i in range(len(tickets)):
        for j in range(i + 1, len(tickets)):
            for k in range(j + 1, len(tickets)):
                for last in range(k + 1, len(tickets)):
                    combination = sorted([tickets[i], tickets[j], tickets[k], tickets[last]])
                    combinations.append(combination)

    # Filter combinations that meet the conditions
    prime_combinations = []
    even_sum_combinations = []
    for combination in combinations:
        if sum(combination) % 2 == 0:  # Check if the sum is even
            even_sum_combinations.append(combination)
        prime_count = sum(1 for num in combination if is_prime(num))
        if prime_count >= 2:  # Check if there are at least two prime numbers
            prime_combinations.append(combination)

    # Calculate the probability
    total_combinations = len(combinations)
    valid_combinations = len(prime_combinations) + len(even_sum_combinations) - len([combination for combination in combinations if sum(combination) % 2 == 0 and sum(1 for num in combination if is_prime(num)) >= 2])
    probability = (valid_combinations / total_combinations) * 100
    return round(probability, 1)
